<?php
namespace Pterodactyl\Services\Nodexa;
use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Http; use RuntimeException;
class FlaxVpsClient { private object $provider; public function __construct(?object $provider=null){$this->provider=$provider?:DB::table('vps_providers')->where('active',true)->first();if(!$this->provider)throw new RuntimeException('Flax VPS provider er ikke konfigureret.');} private function key():string{return Crypt::decryptString($this->provider->api_key);} public function request(string $action,array $params=[],string $method='POST'):array{$key=$this->key();$url=rtrim($this->provider->endpoint,'/').'/api-endpoint.php';$query=array_merge(['key'=>$key,'action'=>$action],$params);$http=Http::timeout(15)->acceptJson()->withToken($key)->withUserAgent('Nodexa-Flax-VPS/1.2');$response=strtoupper($method)==='GET'?$http->get($url,$query):$http->asForm()->post($url,$query);if(!$response->successful())throw new RuntimeException('Flax API HTTP '.$response->status());$json=$response->json();if(!is_array($json))throw new RuntimeException('Ugyldigt svar fra Flax API.');if(($json['status']??null)==='error')throw new RuntimeException((string)($json['data']??$json['message']??'Flax API fejl'));return is_array($json['data']??null)?$json['data']:$json;} private function list(array $r,array $keys):array{foreach($keys as $k)if(isset($r[$k])&&is_array($r[$k]))return array_values($r[$k]);return array_is_list($r)?$r:[];} public function servers():array{return $this->list($this->request('user_servers',[],'GET'),['servers','data','result']);} public function discoverProducts():array{foreach(['products','packages','plans','vps_products','list_products'] as $a){try{$x=$this->list($this->request($a,[],'GET'),['products','packages','plans','data','result']);if($x)return $x;}catch(\Throwable $e){}}return [];} public function discoverOperatingSystems(?string $product=null):array{foreach(['virtualizor_templates','operating_systems','os_templates','templates','oses'] as $a){try{$p=$product?['productId'=>$product]:[];$x=$this->list($this->request($a,$p,'GET'),['templates','virtualizor_templates','operatingSystems','operating_systems','oses','data','result']);if($x)return $x;}catch(\Throwable $e){}}return [];} public function virtualizorTemplates():array{return $this->list($this->request('virtualizor_templates',[],'GET'),['templates','virtualizor_templates','data','result']);} public function wispEggs():array{return $this->list($this->request('wisp-eggs',[],'GET'),['eggs','wisp_eggs','data','result']);} public function info(string $id):array{return $this->request('info',['server_id'=>$id],'GET');} public function power(string $id,string $action):array{if(!in_array($action,['boot','shutdown','restart','poweroff'],true))throw new RuntimeException('Ugyldig VPS handling.');return $this->request($action,['server_id'=>$id]);} public function os(string $id):array{return $this->request('os_info',['server_id'=>$id],'GET');} public function rebuild(string $id,string $os):array{return $this->request('build',['server_id'=>$id,'operatingSystem'=>$os]);} public function create(string $productId,string $osId,?string $gameType=null):array{$params=['productId'=>$productId,'operatingSystem'=>$osId];if($gameType!==null&&$gameType!=='')$params['gameType']=$gameType;return $this->request('create',$params);}}
